USE communityhub;
ALTER TABLE users ADD COLUMN IF NOT EXISTS fivem_license VARCHAR(100) NULL AFTER discord_id;
ALTER TABLE users ADD COLUMN IF NOT EXISTS fivem_name VARCHAR(120) NULL AFTER fivem_license;
CREATE UNIQUE INDEX IF NOT EXISTS uq_users_fivem_license ON users(fivem_license);
CREATE TABLE IF NOT EXISTS fivem_link_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,code_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(code_hash),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fivem_servers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,server_key VARCHAR(80) NOT NULL UNIQUE,hostname VARCHAR(255) NULL,max_players INT UNSIGNED NOT NULL DEFAULT 64,is_online BOOLEAN NOT NULL DEFAULT FALSE,current_players INT UNSIGNED NOT NULL DEFAULT 0,last_heartbeat_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fivem_player_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,server_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,fivem_license VARCHAR(100) NOT NULL,player_name VARCHAR(120) NULL,joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,left_at DATETIME NULL,FOREIGN KEY(server_id) REFERENCES fivem_servers(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(server_id,left_at),INDEX(fivem_license));
CREATE TABLE IF NOT EXISTS patrol_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,server_id BIGINT UNSIGNED NULL,department_id BIGINT UNSIGNED NULL,callsign VARCHAR(50) NULL,status ENUM('active','completed','cancelled') NOT NULL DEFAULT 'active',clocked_in_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,clocked_out_at DATETIME NULL,notes TEXT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(server_id) REFERENCES fivem_servers(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,INDEX(status,clocked_in_at));
INSERT INTO fivem_servers(name,server_key,max_players) SELECT 'Primary FiveM Server','primary',64 WHERE NOT EXISTS(SELECT 1 FROM fivem_servers WHERE server_key='primary');